pub fn camel_to_kebab(s: &String) -> String {
    let mut result = String::new();
    for ch in s.chars() {
        if ch.is_uppercase() {
            result.push("-");
            result.push(ch.to_lowercase().next().unwrap())
        } else {
            result.push(ch)
        }
    }
    result
}

